def applies(scope, path):
    s = scope.split('/')
    p = path.split('/')
    return p[:len(s)] == s

BLOCKS = {'ReadOnly': {'write', 'delete'}, 'CanNotDelete': {'delete'}}
RANK = {'ReadOnly': 0, 'CanNotDelete': 1}

l = int(input())
locks = [input().split() for _ in range(l)]
q = int(input())
for _ in range(q):
    op, path = input().split()
    hits = [(RANK[t], len(s.split('/')), s, t) for s, t in locks
            if applies(s, path) and op in BLOCKS[t]]
    if hits:
        _, _, scope, kind = min(hits)
        print(f'BLOCKED by {kind} at {scope}')
    else:
        print('ALLOWED')
